effect.shader:
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    float t = freeze? 0.0 : acTime;
    vec4 acc = vec4(0.0);
    float n = 0.0;
    float r = roughness*0.04;
    for(int i=0;i<24;i++){
        if(float(i)>=float(samples)) break;
        float a = rand(acScreenNorm*100.0 + float(i) + t)*6.2831;
        float d = rand(acScreenNorm*55.0 + float(i)*1.7 + t)*r;
        vec2 off = vec2(cos(a),sin(a))*d;
        acc += texture2DCv(inputImg.texture, acScreenNorm+off);
        n += 1.0;
    }
    gl_FragColor = acc/n;
}
